});

// 계정 관리 페이지 (권한 확인 후 접근)
router.get('/admin/users', (req, res) => {
    // 세션에서 현재 로그인한 사용자 정보 가져오기
    const userStudentNum = req.session.user?.studentnum;

    if (!userStudentNum) {
        return res.redirect('/users/login');
    }

    // 회장 권한 확인
    const verificate_permSQL = `SELECT president FROM user_permissions WHERE studentNum = ?`;
    db.query(verificate_permSQL, [userStudentNum], (err, result) => {
        if (err) {
            console.error('권한 확인 DB 오류:', err);
            return res.status(500).send('데이터베이스 오류');
        }

        if (result.length === 0 || (!result[0].president)) {
            return res.status(403).send('회장 권한이 필요합니다.');
        }

        // 권한이 있으면 사용자 목록 조회
        const sql = `
            SELECT u.studentNum, u.name, u.grade, 
                 COALESCE(MAX(up.president), false) as president,
                 COALESCE(MAX(up.vice_president), false) as vice_president,
                 COALESCE(MAX(up.rent_perm), false) as rent_perm
           FROM Users u
           LEFT JOIN user_permissions up ON u.studentNum = up.studentNum
           GROUP BY u.studentNum, u.name, u.grade
           ORDER BY u.studentNum
        `;

        db.query(sql, (err, users) => {
            if (err) {
                console.error('DB 오류:', err);
                return res.status(500).send('데이터베이스 오류');
            }
            res.render('users', { title: '사용자 관리', users: users });
        });
    });
});

// 계정 삭제 기능
router.post('/admin/delete-user', (req, res) => {
    const { studentNum } = req.body;

    if (!studentNum) {
        return res.status(400).json({
            success: false,
            message: '학번이 제공되지 않았습니다.'
        });
    }

    // 먼저 president, vice_president 권한 확인
    const checkSql = 'SELECT president, vice_president FROM user_permissions WHERE studentNum = ?';
    db.query(checkSql, [studentNum], (err, permissions) => {
        if (err) {
            console.error('권한 확인 DB 오류:', err);
            return res.status(500).json({
                success: false,
                message: '데이터베이스 오류가 발생했습니다.'
            });
        }

        // 권한이 있는 경우 삭제 불가
        if (permissions.length > 0 && (permissions[0].president || permissions[0].vice_president)) {
            return res.status(403).json({
                success: false,
                message: '회장 또는 부회장은 삭제할 수 없습니다.'
            });
        }

        // 트랜잭션으로 안전하게 삭제
        db.beginTransaction((err) => {
            if (err) {
                console.error('트랜잭션 시작 오류:', err);
                return res.status(500).json({
                    success: false,
                    message: '데이터베이스 오류가 발생했습니다.'
                });
            }

            // user_permissions 테이블에서 삭제 (president, vice_president가 false인 경우만)
            const deletePermissionsSql = 'DELETE FROM user_permissions WHERE studentNum = ? AND president = false AND vice_president = false';
            db.query(deletePermissionsSql, [studentNum], (err, permissionsResult) => {
                if (err) {
                    return db.rollback(() => {
                        console.error('user_permissions 삭제 오류:', err);
                        res.status(500).json({
                            success: false,
                            message: '데이터베이스 오류가 발생했습니다.'
                        });
                    });
                }

                // Users 테이블에서 삭제
                const deleteUserSql = 'DELETE FROM Users WHERE studentNum = ?';
                db.query(deleteUserSql, [studentNum], (err, userResult) => {
                    if (err) {
                        return db.rollback(() => {
                            console.error('Users 삭제 오류:', err);
                            res.status(500).json({
                                success: false,
                                message: '데이터베이스 오류가 발생했습니다.'
                            });
                        });
                    }

                    // 트랜잭션 커밋
                    db.commit((err) => {
                        if (err) {
                            return db.rollback(() => {
                                console.error('트랜잭션 커밋 오류:', err);
                                res.status(500).json({
                                    success: false,
                                    message: '데이터베이스 오류가 발생했습니다.'
                                });
                            });
                        }

                        console.log(`학번 ${studentNum} 계정이 삭제되었습니다.`);
                        res.json({
                            success: true,
                            message: '계정이 성공적으로 삭제되었습니다.'
                        });
                    });
                });
            });
        });
    });
});

/* ✅ 관리자 물건 삭제 기능 */
router.post('/admin/delete-items', (req, res) => {
    const { items } = req.body;

    if (!items || !Array.isArray(items) || items.length === 0) {
        return res.status(400).json({
            success: false,
            message: '삭제할 물건이 선택되지 않았습니다.'
        });
    }

    // 관리자 권한 확인 (선택사항)
    /*
    if (!req.session.user || req.session.user.role !== 'admin') {
        return res.status(403).json({
            success: false,
            message: '관리자 권한이 필요합니다.'
        });
    */

    // 선택된 물건들을 데이터베이스에서 삭제
    const placeholders = items.map(() => '?').join(',');
    const sql = `DELETE FROM Items WHERE itemName IN (${placeholders})`;

    db.query(sql, items, (err, result) => {
        if (err) {
            console.error('DB 삭제 오류:', err);
            return res.status(500).json({
                success: false,
                message: '데이터베이스 오류가 발생했습니다.'
            });
        }

        console.log(`${items.length}개의 물건이 삭제되었습니다:`, items);
        res.json({
            success: true,
            message: `${items.length}개의 물건이 성공적으로 삭제되었습니다.`,
            deletedItems: items
        });
    });
});



//부회장 임명 기능
router.post('/admin/appoint-vice-president', (req, res) => {
    const { studentNum } = req.body;

    if (!studentNum) {
        return res.status(400).json({
            success: false,
            message: '학번이 제공되지 않았습니다.'
        });
    }

    //먼저 해당 사용자가 존재하는지 확인
    const checkUserSql = 'SELECT studentNum FROM Users WHERE studentNum = ?';
    db.query(checkUserSql, [studentNum], (err, users) => {
        if (err) {
            console.error('사용자 확인 DB 오류:', err);
            return res.status(500).json({
                success: false,
                message: '데이터베이스 오류가 발생했습니다.'
            });
        }

        if (users.length === 0) {
            return res.status(404).json({
                success: false,
                message: '해당 학번의 사용자를 찾을 수 없습니다.'
            });
        }

        //이미 부회장인지 확인
        const checkViceSql = 'SELECT vice_president FROM user_permissions WHERE studentNum = ?';
        db.query(checkViceSql, [studentNum], (err, permissions) => {
            if (err) {
                console.error('권한 확인 DB 오류:', err);
                return res.status(500).json({
                    success: false,
                    message: '데이터베이스 오류가 발생했습니다.'
                });
            }

            if (permissions.length > 0 && permissions[0].vice_president) {
                return res.status(400).json({
                    success: false,
                    message: '이미 부회장으로 임명된 사용자입니다.'
                });
            }

            //user_permissions 테이블에 레코드가 있는지 확인하고 업데이트 또는 삽입
            if (permissions.length > 0) {
                // 기존 레코드 업데이트
                const updateSql = 'UPDATE user_permissions SET vice_president = TRUE WHERE studentNum = ?';
                db.query(updateSql, [studentNum], (err, result) => {
                    if (err) {
                        console.error('부회장 임명 DB 오류:', err);
                        return res.status(500).json({
                            success: false,
                            message: '데이터베이스 오류가 발생했습니다.'
                        });
                    }

                    console.log(`학번 ${studentNum}을 부회장으로 임명했습니다.`);
                    res.json({
                        success: true,
                        message: '부회장으로 성공적으로 임명되었습니다.'
                    });
                });
            } else {
                // 새 레코드 삽입
                const insertSql = 'INSERT INTO user_permissions (studentNum, vice_president) VALUES (?, TRUE)';
                db.query(insertSql, [studentNum], (err, result) => {
                    if (err) {
                        console.error('부회장 임명 DB 오류:', err);
                        return res.status(500).json({
                            success: false,
                            message: '데이터베이스 오류가 발생했습니다.'
                        });
                    }

                    console.log(`학번 ${studentNum}을 부회장으로 임명했습니다.`);
                    res.json({
                        success: true,
                        message: '부회장으로 성공적으로 임명되었습니다.'
                    });
                });
            }
        });
    });
});

// 부회장 해임 기능
router.post('/admin/remove-vice-president', (req, res) => {
    const { studentNum } = req.body;

    if (!studentNum) {
        return res.status(400).json({
            success: false,
            message: '학번이 제공되지 않았습니다.'
        });
    }

    // 부회장 권한 확인
    const checkSql = 'SELECT vice_president FROM user_permissions WHERE studentNum = ?';
    db.query(checkSql, [studentNum], (err, permissions) => {
        if (err) {
            console.error('권한 확인 DB 오류:', err);
            return res.status(500).json({
                success: false,
                message: '데이터베이스 오류가 발생했습니다.'
            });
        }

        if (permissions.length === 0 || !permissions[0].vice_president) {
            return res.status(400).json({
                success: false,
                message: '부회장이 아닌 사용자입니다.'
            });
        }

        // 부회장 권한 해제
        const updateSql = 'UPDATE user_permissions SET vice_president = FALSE WHERE studentNum = ?';
        db.query(updateSql, [studentNum], (err, result) => {
            if (err) {
                console.error('부회장 해임 DB 오류:', err);
                return res.status(500).json({
                    success: false,
                    message: '데이터베이스 오류가 발생했습니다.'
                });
            }

            console.log(`학번 ${studentNum}의 부회장 권한을 해임했습니다.`);
            res.json({
                success: true,
                message: '부회장 권한이 성공적으로 해임되었습니다.'
            });
        });
    });
});



module.exports = router;


//히히 오줌발싸

/*
* 예약리스트 쿠키를 검증하여 예약을 진행하는 라우터
* 취소도 여기서 처리함
*/
const express = require('express');
const router = express.Router();
const { db } = require('./IMS_db');

//10~148라인은 옛날 버전, 혹시 모르니 남겨두고 추후 삭제
// ✅ 대여 확정 및 DB 반영 라우트, 이전버전
router.post('/verify-step2', (req, res) => {
    const sessionUser = req.session.user;
    const cookieReserved = req.cookies.reservedItems;

    if (!sessionUser || !cookieReserved) {
        return res.status(401).send('로그인 또는 쿠키 없음');
    }

    const [cookieStudentNum, itemListStr] = cookieReserved.split(':');

    const cookieItemList = itemListStr?.split(',').filter(Boolean).sort();

    // 학번 변조 검사
    if (cookieStudentNum !== sessionUser.studentnum) {
        res.clearCookie('reservedItems');
        return res.status(403).send('쿠키 학번 변조 감지');
    }

    // 이름 조회
    const sqlName = 'SELECT name FROM Users WHERE studentNum = ?';
    db.query(sqlName, [sessionUser.studentnum], (err, results) => {
        if (err || results.length === 0) {
            return res.status(500).send('DB 오류 또는 사용자 없음');
        }

        const userName = results[0].name;

        // 기존 대여 내역 조회
        const sqlRent = 'SELECT itemName FROM Rent_status WHERE studentNum = ?';
        db.query(sqlRent, [sessionUser.studentnum], (err, rentResults) => {
            if (err) {
                return res.status(500).send('대여 내역 조회 실패');
            }

            const dbItemList = rentResults.map(row => row.itemName);
            const alreadyRentedSet = new Set(dbItemList);

            // 이미 대여된 항목 제외
            const newItemsToRent = cookieItemList.filter(item => !alreadyRentedSet.has(item));

            if (newItemsToRent.length === 0) {
                return res.send({
                    success: true,
                    message: '이미 대여된 항목입니다.',
                    skipped: cookieItemList
                });
            }

            // rentToHour 기본값 1시간으로 설정
            const insertValues = newItemsToRent.map(item => [item, userName, 1, new Date(), cookieStudentNum]);
            const sqlInsert = 'INSERT INTO Rent_status (itemName, whoAreRent, rentToHour, date, studentNum) VALUES ?';
            const rentStatusSqlInsert = 'UPDATE Items SET status = 1 WHERE itemName = ?';

            db.query(sqlInsert, [insertValues], (err, insertResult) => {
                if (err) {
                    console.error('[❌ INSERT 실패]', err);
                    return res.status(500).send('대여 정보 저장 실패');
                }

                // ✅ Log_rent에도 대여 기록 INSERT
                const logValues = newItemsToRent.map(item => [userName, item.itemName]);
                const sqlLogInsert = 'INSERT INTO Log_rent (name, itemName) VALUES ?';
                db.query(sqlLogInsert, [logValues], (logErr) => {
                    if (logErr) console.error('[❌ Log_rent INSERT 실패]', logErr);
                });
                // 모든 아이템의 status 업데이트
                Promise.all(newItemsToRent.map(item =>
                    new Promise((resolve, reject) => {
                        db.query(rentStatusSqlInsert, [item], (err, results) => {
                            if (err) reject(err);
                            else resolve(results);
                        });
                    })
                ))
                    .then(() => {
                        res.clearCookie('reservedItems');
                        return res.send({
                            success: true,
                            message: '대여 완료 ✅',
                            rented: newItemsToRent,
                            skipped: dbItemList.filter(item => cookieItemList.includes(item))
                        });
                    })
                    .catch(err => {
                        console.error('렌트 상태 조정 실패: ', err);
                        return res.status(500).send('렌트 상태 조정 실패');
                    });
            });
        });
    });
});

// ✅ 대여 취소 라우트 (기록 유무 확인 후 삭제), 이전버전
router.post('/cancel', (req, res) => {
    const sessionUser = req.session.user;
    const itemName = req.body.itemName;

    if (!sessionUser) {
        return res.status(401).json({ success: false, message: '세션 없음' });
    }

    const sqlName = 'SELECT name FROM Users WHERE studentNum = ?';
    db.query(sqlName, [sessionUser.studentnum], (err, results) => {
        if (err || results.length === 0) {
            return res.status(500).json({ success: false, message: '사용자 조회 실패' });
        }

        const userName = results[0].name;

        const sqlCheck = 'SELECT * FROM Rent_status WHERE itemName = ? AND studentNum = ?';
        db.query(sqlCheck, [itemName, sessionUser.studentnum], (err, checkResult) => {
            if (err) {
                return res.status(500).json({ success: false, message: '대여 기록 확인 실패' });
            }

            if (checkResult.length === 0) {
                return res.json({ success: false, message: `${itemName}은(는) 현재 대여하지 않았습니다.` });
            }

            // ✅ 먼저 대여 기간 정보를 조회
            const sqlGetRentInfo = `
                SELECT lr.rentTime, rs.rentToHour
                FROM Log_rent lr
                JOIN Rent_status rs ON lr.itemName = rs.itemName AND lr.name = rs.whoAreRent
                WHERE lr.name = ? AND lr.itemName = ? AND lr.returnTime IS NULL
                ORDER BY lr.rentTime DESC
                LIMIT 1
            `;

            db.query(sqlGetRentInfo, [userName, itemName], (err, rentInfoResults) => {
                if (err) {
                    console.error('[❌ 대여 정보 조회 실패]', err);
                    return res.status(500).json({ success: false, message: '대여 정보 조회 실패' });
                }

                const rentInfo = rentInfoResults.length > 0 ? rentInfoResults[0] : null;

                const sqlDelete = 'DELETE FROM Rent_status WHERE itemName = ? AND studentNum = ?';
                db.query(sqlDelete, [itemName, sessionUser.studentnum], (err, deleteResult) => {
                    if (err) {
                        console.error('[❌ 대여 취소 실패]', err);
                        return res.status(500).json({ success: false, message: '대여 취소 실패' });
                    }

                    const sqlUpdateStatus = 'UPDATE Items SET status = 0 WHERE itemName = ?';
                    db.query(sqlUpdateStatus, [itemName], (err, results) => {
                        if (err) {
                            console.error('[❌ status 업데이트 실패]', err);
                            return res.status(500).json({ success: false, message: 'status 업데이트 실패' });
                        }

                        // ✅ Log_rent 반납 기록 + 조건부 연체시간 계산
                        if (rentInfo && rentInfo.rentTime && rentInfo.rentToHour) {
                            // 먼저 연체 여부를 확인
                            const currentTime = new Date();
                            const rentTime = new Date(rentInfo.rentTime);
                            const rentEndTime = new Date(rentTime.getTime() + rentInfo.rentToHour * 60 * 60 * 1000);
                            const isOverdue = currentTime > rentEndTime;

                            const sqlUpdateLog = `
                                UPDATE Log_rent
                                SET returnTime = NOW(),
                                    delinquencyTime = CASE 
                                        WHEN TIMESTAMPDIFF(HOUR, ?, NOW()) > ?
                                        THEN SEC_TO_TIME(TIMESTAMPDIFF(SECOND, DATE_ADD(?, INTERVAL ? HOUR), NOW()))
                                        ELSE NULL
                                    END
                                WHERE name = ? AND itemName = ? AND returnTime IS NULL
                                ORDER BY rentTime DESC
                                LIMIT 1
                            `;

                            db.query(sqlUpdateLog, [
                                rentInfo.rentTime,
                                rentInfo.rentToHour,
                                rentInfo.rentTime,
                                rentInfo.rentToHour,
                                userName,
                                itemName
                            ], (logErr) => {
                                if (logErr) {
                                    console.error('[❌ Log_rent UPDATE 실패]', logErr);
                                    return;
                                }

                                // ✅ 연체가 감지된 경우 rent_perm을 0으로 설정
                                if (isOverdue) {
                                    const sqlUpdatePerm = `
                                        UPDATE user_permissions 
                                        SET rent_perm = 0 
                                        WHERE studentNum = ?
                                    `;

                                    db.query(sqlUpdatePerm, [sessionUser.studentnum], (permErr, permResult) => {
                                        if (permErr) {
                                            console.error('[❌ 권한 제한 실패]', permErr);
                                        } else if (permResult.affectedRows > 0) {
                                            console.log(`[ 연체로 인한 권한 제한] ${userName}(${sessionUser.studentnum}) - 아이템: ${itemName}`);
                                        } else {
                                            console.log(`[⚠️ 권한 제한 대상 없음] ${userName}(${sessionUser.studentnum}) - user_permissions 레코드가 없습니다`);
                                        }
                                    });
                                }
                            });
                        } else {
                            console.error('[❌ 대여 정보 누락으로 연체시간 계산 불가]: ', itemName);
                        }

                        return res.json({ success: true, message: `${itemName} 대여 취소 완료` });
                    });
                });
            });
        });
    });
});


const actionMode ={
    rent: handleRental,
    return: handleReturn,
};

router.post('/verify-step3', (req, res) => {
    const sessionUser = req.session.user;
    const cookieReserved = req.cookies.reservedItems;
    const cookieReturn = req.cookies.returnItemList;

    if (!sessionUser) {
        return res.status(401).send('로그인 후 시도해주세요');
    }

    const hasReserved = cookieReserved && cookieReserved.length > 0;
    const hasReturn = cookieReturn && cookieReturn.length > 0;
    if(!hasReturn && !hasReserved) return res.status(400).json({ success: false, message:'처리할 항목이 없음'});

    const results = { success: true, messages: [] };
    const operations = [];

    if (hasReserved) {
        const [cookieStudentNum, itemListStr] = cookieReserved.split(':');
        const cookieItemEntries = itemListStr?.split(',').filter(Boolean);
        const cookieItemData = cookieItemEntries.map(entry => {
            if (entry.includes('#')) {
                const [itemName, hours] = entry.split('#');
                return { itemName, hours: parseInt(hours) || 1 };
            } else {
                // 기존 형식 호환성
                return { itemName: entry, hours: 1 };
            }
        });
        if (cookieStudentNum !== sessionUser.studentnum) {
            res.clearCookie('reservedItems');
            return res.status(403).json({ success: false, message: '쿠키 학번 변조 감지' });
        }

        if(cookieItemData.length <= 0) return;

        operations.push(
            new Promise((resolve, reject) => {
                handleRental(req, res, cookieStudentNum, cookieItemData, (result) => {
                    if (result.success) {
                        results.messages.push(`대여: ${result.message}`);
                        res.clearCookie('reservedItems');
                    }
                    resolve(result);
                });
            })
        );
    }

    if (hasReturn) {
        const [returnStudentNum, returnItemListStr] = cookieReturn.split(':');
        const returnItemList = returnItemListStr?.split(',').filter(Boolean).sort();

        if (returnStudentNum !== sessionUser.studentnum) {
            res.clearCookie('returnItemList');
            return res.status(403).json({ success: false, message: '반납 쿠키 학번 변조 감지' });
        }

        if(returnItemList.length <= 0) return;

        operations.push(
            new Promise((resolve, reject) => {
                handleReturn(req, res, returnStudentNum, returnItemList, (result) => {
                    if (result.success) {
                        results.messages.push(`반납: ${result.message}`);
                        res.clearCookie('returnItemList');
                    }
                    resolve(result);
                });
            })
        );
    }

    Promise.all(operations)
        .then(operationResults => {
            const allSuccess = operationResults.every(result => result.success);
            return res.json({
                success: allSuccess,
                message: results.messages.join(' / '),
                details: operationResults
            });
        })
        .catch(error => {
            console.error('처리 중 오류:', error);
            return res.status(500).json({ success: false, message: '처리 중 오류가 발생했습니다' });
        });
});

function handleRental(req, res, cookieStudentNum, cookieItemData, callback) {
    const sqlName = 'SELECT name FROM Users WHERE studentNum = ?';
    db.query(sqlName, [cookieStudentNum], (err, results) => {
        if (err || results.length === 0) {
            return callback({ success: false, message: 'DB 오류 또는 사용자 없음' });
        }

        const userName = results[0].name;

        //지금은 이미 대여중인지 먼저 확인하는 순서로 시작하는데, 여기에 대여 금지상태인지 먼저 판단하는 코드를 짜면 되겠어
        const sqlRent = 'SELECT itemName FROM Rent_status WHERE studentNum = ?';
        db.query(sqlRent, [cookieStudentNum], (err, rentResults) => {
            if (err) {
                return callback({ success: false, message: '대여 내역 조회 실패' });
            }

            const dbItemList = rentResults.map(row => row.itemName);
            const alreadyRentedSet = new Set(dbItemList);

            const newItemsToRent = cookieItemData.filter(item => !alreadyRentedSet.has(item.itemName));


            if (newItemsToRent.length === 0) {
                res.clearCookie('reservedItems');
                return res.send({
                    success: true,
                    message: '이미 대여된 항목입니다.',
                    skipped: cookieItemData.map(item => item.itemName)
                });
            }

            const insertValues = newItemsToRent.map(item => [
                item.itemName,
                userName,
                item.hours,
                new Date(),
                cookieStudentNum
            ]);

            const sqlInsert = 'INSERT INTO Rent_status (itemName, whoAreRent, rentToHour, date, studentNum) VALUES ?';
            db.query(sqlInsert, [insertValues], (err, insertResult) => {
                if (err) {
                    return callback({ success: false, message: '대여정보 저장 실패' });
                }

                // ✅ Log_rent 기록 추가
                const logValues = newItemsToRent.map(item => [userName, item.itemName]);
                const sqlLogInsert = 'INSERT INTO Log_rent (name, itemName) VALUES ?';
                db.query(sqlLogInsert, [logValues], (logErr) => {
                    if (logErr) console.error('[❌ Log_rent INSERT 실패]', logErr);
                });

                Promise.all(newItemsToRent.map(item =>
                    new Promise((resolve, reject) => {
                        const sqlUpdate = 'UPDATE Items SET status = 1 WHERE itemName = ?';
                        db.query(sqlUpdate, [item.itemName], (err, results) => {
                            if (err) reject(err);
                            else resolve(results);
                        });
                    })
                ))
                    .then(() => {
                        const rentedItems = newItemsToRent.map(item => `${item.itemName}(${item.hours}시간)`);
                        callback({
                            success: true,
                            message: `대여 완료: ${rentedItems.join(', ')}`,
                            rented: newItemsToRent
                        });
                    })
                    .catch(err => {
                        callback({ success: false, message: '렌트 상태 조정 실패' });
                    });
            });
        });
    });
}

function handleReturn(req, res, cookieStudentNum ,cookieItemList, callback) {
    const sqlName = 'SELECT name FROM Users WHERE studentNum = ?';
    db.query(sqlName, [cookieStudentNum], (err, results) => {
        if (err || results.length === 0) {
            return callback({ success: false, message: '사용자 조회 실패' });
        }

        const userName = results[0].name;

        const sqlCheck = 'SELECT itemName FROM Rent_status WHERE studentNum = ?';
        db.query(sqlCheck, [cookieStudentNum], (err, checkResult) => {
            if (err) {
                return callback({ success: false, message: '대여 기록 확인 실패' });
            }

            const dbItemList = checkResult.map(row => row.itemName);
            const targetItemList = cookieItemList.filter(item => dbItemList.includes(item));

            if (targetItemList.length === 0) {
                return callback({ success: false, message: '반납할 수 있는 항목이 없습니다' });
            }

            //먼저 대여 기간 정보를 조회하여 저장
            const getRentInfoPromises = targetItemList.map(item =>
                new Promise((resolve, reject) => {
                    const sqlGetRentInfo = `
                        SELECT lr.rentTime, rs.rentToHour
                        FROM Log_rent lr
                        JOIN Rent_status rs ON lr.itemName = rs.itemName AND lr.name = rs.whoAreRent
                        WHERE lr.name = ? AND lr.itemName = ? AND lr.returnTime IS NULL
                        ORDER BY lr.rentTime DESC
                        LIMIT 1
                    `;

                    db.query(sqlGetRentInfo, [userName, item], (err, results) => {
                        if (err) {
                            reject(err);
                            return;
                        }

                        if (results.length === 0) {
                            console.error('대여 정보를 찾을 수 없음', item);
                            resolve({ itemName: item, rentTime: null, rentToHour: null });
                            return;
                        }

                        resolve({
                            itemName: item,
                            rentTime: results[0].rentTime,
                            rentToHour: results[0].rentToHour
                        });
                    });
                })
            );

            Promise.all(getRentInfoPromises)
                .then(rentInfoList => {
                    //대여중인 상태를 나타내는 Rent_status테이블 업데이트
                    const deletePromises = targetItemList.map(item =>
                        new Promise((resolve, reject) => {
                            const sqlDelete = 'DELETE FROM Rent_status WHERE itemName = ? AND studentNum = ?';
                            db.query(sqlDelete, [item, cookieStudentNum], (err, result) => {
                                if (err) reject(err);
                                else resolve(result);
                            });
                        })
                    );

                    return Promise.all([Promise.all(deletePromises), rentInfoList]);
                })
                .then(([deleteResults, rentInfoList]) => {
                    //Items 테이블 status 업데이트
                    const updatePromises = targetItemList.map(item =>
                        new Promise((resolve, reject) => {
                            const sqlUpdateStatus = 'UPDATE Items SET status = 0 WHERE itemName = ?';
                            db.query(sqlUpdateStatus, [item], (err, result) => {
                                if (err) reject(err);
                                else resolve(result);
                            });
                        })
                    );

                    return Promise.all([Promise.all(updatePromises), rentInfoList]);
                })
                .then(([updateResults, rentInfoList]) => {
                    //Log_rent 반납 처리 + 조건부 연체시간 계산
                    rentInfoList.forEach(rentInfo => {
                        if (!rentInfo.rentTime || !rentInfo.rentToHour) {
                            console.error('대여 정보 누락: ', rentInfo.itemName);
                            return;
                        }

                        // 먼저 연체 여부를 확인
                        const currentTime = new Date();
                        const rentTime = new Date(rentInfo.rentTime);
                        const rentEndTime = new Date(rentTime.getTime() + rentInfo.rentToHour * 60 * 60 * 1000);
                        const isOverdue = currentTime > rentEndTime;

                        //대여 기간 초과 여부 확인 후 연체시간 계산
                        const sqlUpdateLog = `
                            UPDATE Log_rent
                            SET returnTime = NOW(),
                                delinquencyTime = CASE
                                    WHEN NOW() > DATE_ADD(?, INTERVAL ? HOUR)
                                    THEN SEC_TO_TIME(TIMESTAMPDIFF(SECOND, DATE_ADD(?, INTERVAL ? HOUR), NOW()))
                                    ELSE NULL
                                END
                            WHERE name = ? AND itemName = ?
                              AND returnTime IS NULL
                            ORDER BY rentTime DESC
                            LIMIT 1
                        `;

                        db.query(sqlUpdateLog, [
                            rentInfo.rentTime,
                            rentInfo.rentToHour,
                            rentInfo.rentTime,
                            rentInfo.rentToHour,
                            userName,
                            rentInfo.itemName
                        ], (logErr) => {
                            if (logErr) {
                                console.error('[❌ Log_rent UPDATE 실패]: ', logErr);
                                return;
                            }

                            // ✅ 연체가 감지된 경우 rent_perm을 0으로 설정
                            if (isOverdue) {
                                const sqlGetStudentNum = 'SELECT studentNum FROM Users WHERE name = ?';
                                db.query(sqlGetStudentNum, [userName], (err, userResults) => {
                                    if (err) {
                                        console.error('[❌ 사용자 학번 조회 실패]: ', err);
                                        return;
                                    }

                                    if (userResults.length === 0) {
                                        console.error('[❌ 사용자를 찾을 수 없음]: ', userName);
                                        return;
                                    }

                                    const studentNum = userResults[0].studentNum;

                                    // user_permissions에서 rent_perm을 0으로 설정
                                    const sqlUpdatePerm = `
                                        UPDATE user_permissions 
                                        SET rent_perm = 0 
                                        WHERE studentNum = ?
                                    `;

                                    db.query(sqlUpdatePerm, [studentNum], (permErr, permResult) => {
                                        if (permErr) {
                                            console.error('[❌ 권한 제한 실패]', permErr);
                                        } else if (permResult.affectedRows > 0) {
                                            console.log(`[ 연체로 인한 권한 제한] ${userName}(${studentNum}) - 아이템: ${rentInfo.itemName}`);
                                        } else {
                                            console.log(`[⚠️ 권한 제한 대상 없음] ${userName}(${studentNum}) - user_permissions 레코드가 없습니다`);
                                        }
                                    });
                                });
                            }
                        });
                    });

                    callback({ success: true, message: '반납 완료' });
                })
                .catch(err => {
                    console.error('[❌ 반납 처리 중 오류]: ', err);
                    callback({ success: false, message: '반납 처리 실패' });
                });
        });
    });
}

module.exports = router;

/*
* 예약리스트 쿠키를 검증하여 예약을 진행하는 라우터
* 취소도 여기서 처리함
*/
const express = require('express');
const router = express.Router();
const { db } = require('./IMS_db');

//10~148라인은 옛날 버전, 혹시 모르니 남겨두고 추후 삭제
// ✅ 대여 확정 및 DB 반영 라우트, 이전버전
router.post('/verify-step2', (req, res) => {
    const sessionUser = req.session.user;
    const cookieReserved = req.cookies.reservedItems;

    if (!sessionUser || !cookieReserved) {
        return res.status(401).send('로그인 또는 쿠키 없음');
    }

    const [cookieStudentNum, itemListStr] = cookieReserved.split(':');

    const cookieItemList = itemListStr?.split(',').filter(Boolean).sort();

    // 학번 변조 검사
    if (cookieStudentNum !== sessionUser.studentnum) {
        res.clearCookie('reservedItems');
        return res.status(403).send('쿠키 학번 변조 감지');
    }

    // 이름 조회
    const sqlName = 'SELECT name FROM Users WHERE studentNum = ?';
    db.query(sqlName, [sessionUser.studentnum], (err, results) => {
        if (err || results.length === 0) {
            return res.status(500).send('DB 오류 또는 사용자 없음');
        }

        const userName = results[0].name;

        // 기존 대여 내역 조회
        const sqlRent = 'SELECT itemName FROM Rent_status WHERE studentNum = ?';
        db.query(sqlRent, [sessionUser.studentnum], (err, rentResults) => {
            if (err) {
                return res.status(500).send('대여 내역 조회 실패');
            }

            const dbItemList = rentResults.map(row => row.itemName);
            const alreadyRentedSet = new Set(dbItemList);

            // 이미 대여된 항목 제외
            const newItemsToRent = cookieItemList.filter(item => !alreadyRentedSet.has(item));

            if (newItemsToRent.length === 0) {
                return res.send({
                    success: true,
                    message: '이미 대여된 항목입니다.',
                    skipped: cookieItemList
                });
            }

            // rentToHour 기본값 1시간으로 설정
            const insertValues = newItemsToRent.map(item => [item, userName, 1, new Date(), cookieStudentNum]);
            const sqlInsert = 'INSERT INTO Rent_status (itemName, whoAreRent, rentToHour, date, studentNum) VALUES ?';
            const rentStatusSqlInsert = 'UPDATE Items SET status = 1 WHERE itemName = ?';

            db.query(sqlInsert, [insertValues], (err, insertResult) => {
                if (err) {
                    console.error('[❌ INSERT 실패]', err);
                    return res.status(500).send('대여 정보 저장 실패');
                }

                // ✅ Log_rent에도 대여 기록 INSERT
                const logValues = newItemsToRent.map(item => [userName, item.itemName]);
                const sqlLogInsert = 'INSERT INTO Log_rent (name, itemName) VALUES ?';
                db.query(sqlLogInsert, [logValues], (logErr) => {
                    if (logErr) console.error('[❌ Log_rent INSERT 실패]', logErr);
                });
                // 모든 아이템의 status 업데이트
                Promise.all(newItemsToRent.map(item =>
                    new Promise((resolve, reject) => {
                        db.query(rentStatusSqlInsert, [item], (err, results) => {
                            if (err) reject(err);
                            else resolve(results);
                        });
                    })
                ))
                    .then(() => {
                        res.clearCookie('reservedItems');
                        return res.send({
                            success: true,
                            message: '대여 완료 ✅',
                            rented: newItemsToRent,
                            skipped: dbItemList.filter(item => cookieItemList.includes(item))
                        });
                    })
                    .catch(err => {
                        console.error('렌트 상태 조정 실패: ', err);
                        return res.status(500).send('렌트 상태 조정 실패');
                    });
            });
        });
    });
});

// ✅ 대여 취소 라우트 (기록 유무 확인 후 삭제), 이전버전
router.post('/cancel', (req, res) => {
    const sessionUser = req.session.user;
    const itemName = req.body.itemName;

    if (!sessionUser) {
        return res.status(401).json({ success: false, message: '세션 없음' });
    }

    const sqlName = 'SELECT name FROM Users WHERE studentNum = ?';
    db.query(sqlName, [sessionUser.studentnum], (err, results) => {
        if (err || results.length === 0) {
            return res.status(500).json({ success: false, message: '사용자 조회 실패' });
        }

        const userName = results[0].name;

        const sqlCheck = 'SELECT * FROM Rent_status WHERE itemName = ? AND studentNum = ?';
        db.query(sqlCheck, [itemName, sessionUser.studentnum], (err, checkResult) => {
            if (err) {
                return res.status(500).json({ success: false, message: '대여 기록 확인 실패' });
            }

            if (checkResult.length === 0) {
                return res.json({ success: false, message: `${itemName}은(는) 현재 대여하지 않았습니다.` });
            }

            // ✅ 먼저 대여 기간 정보를 조회
            const sqlGetRentInfo = `
                SELECT lr.rentTime, rs.rentToHour
                FROM Log_rent lr
                JOIN Rent_status rs ON lr.itemName = rs.itemName AND lr.name = rs.whoAreRent
                WHERE lr.name = ? AND lr.itemName = ? AND lr.returnTime IS NULL
                ORDER BY lr.rentTime DESC
                LIMIT 1
            `;

            db.query(sqlGetRentInfo, [userName, itemName], (err, rentInfoResults) => {
                if (err) {
                    console.error('[❌ 대여 정보 조회 실패]', err);
                    return res.status(500).json({ success: false, message: '대여 정보 조회 실패' });
                }

                const rentInfo = rentInfoResults.length > 0 ? rentInfoResults[0] : null;

                const sqlDelete = 'DELETE FROM Rent_status WHERE itemName = ? AND studentNum = ?';
                db.query(sqlDelete, [itemName, sessionUser.studentnum], (err, deleteResult) => {
                    if (err) {
                        console.error('[❌ 대여 취소 실패]', err);
                        return res.status(500).json({ success: false, message: '대여 취소 실패' });
                    }

                    const sqlUpdateStatus = 'UPDATE Items SET status = 0 WHERE itemName = ?';
                    db.query(sqlUpdateStatus, [itemName], (err, results) => {
                        if (err) {
                            console.error('[❌ status 업데이트 실패]', err);
                            return res.status(500).json({ success: false, message: 'status 업데이트 실패' });
                        }

                        // ✅ Log_rent 반납 기록 + 조건부 연체시간 계산
                        if (rentInfo && rentInfo.rentTime && rentInfo.rentToHour) {
                            // 먼저 연체 여부를 확인
                            const currentTime = new Date();
                            const rentTime = new Date(rentInfo.rentTime);
                            const rentEndTime = new Date(rentTime.getTime() + rentInfo.rentToHour * 60 * 60 * 1000);
                            const isOverdue = currentTime > rentEndTime;

                            const sqlUpdateLog = `
                                UPDATE Log_rent
                                SET returnTime = NOW(),
                                    delinquencyTime = CASE 
                                        WHEN TIMESTAMPDIFF(HOUR, ?, NOW()) > ?
                                        THEN SEC_TO_TIME(TIMESTAMPDIFF(SECOND, DATE_ADD(?, INTERVAL ? HOUR), NOW()))
                                        ELSE NULL
                                    END
                                WHERE name = ? AND itemName = ? AND returnTime IS NULL
                                ORDER BY rentTime DESC
                                LIMIT 1
                            `;

                            db.query(sqlUpdateLog, [
                                rentInfo.rentTime,
                                rentInfo.rentToHour,
                                rentInfo.rentTime,
                                rentInfo.rentToHour,
                                userName,
                                itemName
                            ], (logErr) => {
                                if (logErr) {
                                    console.error('[❌ Log_rent UPDATE 실패]', logErr);
                                    return;
                                }

                                // ✅ 연체가 감지된 경우 rent_perm을 0으로 설정
                                if (isOverdue) {
                                    const sqlUpdatePerm = `
                                        UPDATE user_permissions 
                                        SET rent_perm = 0 
                                        WHERE studentNum = ?
                                    `;

                                    db.query(sqlUpdatePerm, [sessionUser.studentnum], (permErr, permResult) => {
                                        if (permErr) {
                                            console.error('[❌ 권한 제한 실패]', permErr);
                                        } else if (permResult.affectedRows > 0) {
                                            console.log(`[ 연체로 인한 권한 제한] ${userName}(${sessionUser.studentnum}) - 아이템: ${itemName}`);
                                        } else {
                                            console.log(`[⚠️ 권한 제한 대상 없음] ${userName}(${sessionUser.studentnum}) - user_permissions 레코드가 없습니다`);
                                        }
                                    });
                                }
                            });
                        } else {
                            console.error('[❌ 대여 정보 누락으로 연체시간 계산 불가]: ', itemName);
                        }

                        return res.json({ success: true, message: `${itemName} 대여 취소 완료` });
                    });
                });
            });
        });
    });
});


const actionMode ={
    rent: handleRental,
    return: handleReturn,
};

router.post('/verify-step3', (req, res) => {
    const sessionUser = req.session.user;
    const cookieReserved = req.cookies.reservedItems;
    const cookieReturn = req.cookies.returnItemList;

    if (!sessionUser) {
        return res.status(401).send('로그인 후 시도해주세요');
    }

    const hasReserved = cookieReserved && cookieReserved.length > 0;
    const hasReturn = cookieReturn && cookieReturn.length > 0;
    if(!hasReturn && !hasReserved) return res.status(400).json({ success: false, message:'처리할 항목이 없음'});

    const results = { success: true, messages: [] };
    const operations = [];

    if (hasReserved) {
        const [cookieStudentNum, itemListStr] = cookieReserved.split(':');
        const cookieItemEntries = itemListStr?.split(',').filter(Boolean);
        const cookieItemData = cookieItemEntries.map(entry => {
            if (entry.includes('#')) {
                const [itemName, hours] = entry.split('#');
                return { itemName, hours: parseInt(hours) || 1 };
            } else {
                // 기존 형식 호환성
                return { itemName: entry, hours: 1 };
            }
        });
        if (cookieStudentNum !== sessionUser.studentnum) {
            res.clearCookie('reservedItems');
            return res.status(403).json({ success: false, message: '쿠키 학번 변조 감지' });
        }

        if(cookieItemData.length <= 0) return;

        operations.push(
            new Promise((resolve, reject) => {
                handleRental(req, res, cookieStudentNum, cookieItemData, (result) => {
                    if (result.success) {
                        results.messages.push(`대여: ${result.message}`);
                        res.clearCookie('reservedItems');
                    }
                    resolve(result);
                });
            })
        );
    }

    if (hasReturn) {
        const [returnStudentNum, returnItemListStr] = cookieReturn.split(':');
        const returnItemList = returnItemListStr?.split(',').filter(Boolean).sort();

        if (returnStudentNum !== sessionUser.studentnum) {
            res.clearCookie('returnItemList');
            return res.status(403).json({ success: false, message: '반납 쿠키 학번 변조 감지' });
        }

        if(returnItemList.length <= 0) return;

        operations.push(
            new Promise((resolve, reject) => {
                handleReturn(req, res, returnStudentNum, returnItemList, (result) => {
                    if (result.success) {
                        results.messages.push(`반납: ${result.message}`);
                        res.clearCookie('returnItemList');
                    }
                    resolve(result);
                });
            })
        );
    }

    Promise.all(operations)
        .then(operationResults => {
            const allSuccess = operationResults.every(result => result.success);
            return res.json({
                success: allSuccess,
                message: results.messages.join(' / '),
                details: operationResults
            });
        })
        .catch(error => {
            console.error('처리 중 오류:', error);
            return res.status(500).json({ success: false, message: '처리 중 오류가 발생했습니다' });
        });
});

function handleRental(req, res, cookieStudentNum, cookieItemData, callback) {
    const sqlName = 'SELECT name FROM Users WHERE studentNum = ?';
    db.query(sqlName, [cookieStudentNum], (err, results) => {
        if (err || results.length === 0) {
            return callback({ success: false, message: 'DB 오류 또는 사용자 없음' });
        }

        const userName = results[0].name;

        //지금은 이미 대여중인지 먼저 확인하는 순서로 시작하는데, 여기에 대여 금지상태인지 먼저 판단하는 코드를 짜면 되겠어
        const sqlRent = 'SELECT itemName FROM Rent_status WHERE studentNum = ?';
        db.query(sqlRent, [cookieStudentNum], (err, rentResults) => {
            if (err) {
                return callback({ success: false, message: '대여 내역 조회 실패' });
            }

            const dbItemList = rentResults.map(row => row.itemName);
            const alreadyRentedSet = new Set(dbItemList);

            const newItemsToRent = cookieItemData.filter(item => !alreadyRentedSet.has(item.itemName));


            if (newItemsToRent.length === 0) {
                res.clearCookie('reservedItems');
                return res.send({
                    success: true,
                    message: '이미 대여된 항목입니다.',
                    skipped: cookieItemData.map(item => item.itemName)
                });
            }

            const insertValues = newItemsToRent.map(item => [
                item.itemName,
                userName,
                item.hours,
                new Date(),
                cookieStudentNum
            ]);

            const sqlInsert = 'INSERT INTO Rent_status (itemName, whoAreRent, rentToHour, date, studentNum) VALUES ?';
            db.query(sqlInsert, [insertValues], (err, insertResult) => {
                if (err) {
                    return callback({ success: false, message: '대여정보 저장 실패' });
                }

                // ✅ Log_rent 기록 추가
                const logValues = newItemsToRent.map(item => [userName, item.itemName]);
                const sqlLogInsert = 'INSERT INTO Log_rent (name, itemName) VALUES ?';
                db.query(sqlLogInsert, [logValues], (logErr) => {
                    if (logErr) console.error('[❌ Log_rent INSERT 실패]', logErr);
                });

                Promise.all(newItemsToRent.map(item =>
                    new Promise((resolve, reject) => {
                        const sqlUpdate = 'UPDATE Items SET status = 1 WHERE itemName = ?';
                        db.query(sqlUpdate, [item.itemName], (err, results) => {
                            if (err) reject(err);
                            else resolve(results);
                        });
                    })
                ))
                    .then(() => {
                        const rentedItems = newItemsToRent.map(item => `${item.itemName}(${item.hours}시간)`);
                        callback({
                            success: true,
                            message: `대여 완료: ${rentedItems.join(', ')}`,
                            rented: newItemsToRent
                        });
                    })
                    .catch(err => {
                        callback({ success: false, message: '렌트 상태 조정 실패' });
                    });
            });
        });
    });
}

function handleReturn(req, res, cookieStudentNum ,cookieItemList, callback) {
    const sqlName = 'SELECT name FROM Users WHERE studentNum = ?';
    db.query(sqlName, [cookieStudentNum], (err, results) => {
        if (err || results.length === 0) {
            return callback({ success: false, message: '사용자 조회 실패' });
        }

        const userName = results[0].name;

        const sqlCheck = 'SELECT itemName FROM Rent_status WHERE studentNum = ?';
        db.query(sqlCheck, [cookieStudentNum], (err, checkResult) => {
            if (err) {
                return callback({ success: false, message: '대여 기록 확인 실패' });
            }

            const dbItemList = checkResult.map(row => row.itemName);
            const targetItemList = cookieItemList.filter(item => dbItemList.includes(item));

            if (targetItemList.length === 0) {
                return callback({ success: false, message: '반납할 수 있는 항목이 없습니다' });
            }

            //먼저 대여 기간 정보를 조회하여 저장
            const getRentInfoPromises = targetItemList.map(item =>
                new Promise((resolve, reject) => {
                    const sqlGetRentInfo = `
                        SELECT lr.rentTime, rs.rentToHour
                        FROM Log_rent lr
                        JOIN Rent_status rs ON lr.itemName = rs.itemName AND lr.name = rs.whoAreRent
                        WHERE lr.name = ? AND lr.itemName = ? AND lr.returnTime IS NULL
                        ORDER BY lr.rentTime DESC
                        LIMIT 1
                    `;

                    db.query(sqlGetRentInfo, [userName, item], (err, results) => {
                        if (err) {
                            reject(err);
                            return;
                        }

                        if (results.length === 0) {
                            console.error('대여 정보를 찾을 수 없음', item);
                            resolve({ itemName: item, rentTime: null, rentToHour: null });
                            return;
                        }

                        resolve({
                            itemName: item,
                            rentTime: results[0].rentTime,
                            rentToHour: results[0].rentToHour
                        });
                    });
                })
            );

            Promise.all(getRentInfoPromises)
                .then(rentInfoList => {
                    //대여중인 상태를 나타내는 Rent_status테이블 업데이트
                    const deletePromises = targetItemList.map(item =>
                        new Promise((resolve, reject) => {
                            const sqlDelete = 'DELETE FROM Rent_status WHERE itemName = ? AND studentNum = ?';
                            db.query(sqlDelete, [item, cookieStudentNum], (err, result) => {
                                if (err) reject(err);
                                else resolve(result);
                            });
                        })
                    );

                    return Promise.all([Promise.all(deletePromises), rentInfoList]);
                })
                .then(([deleteResults, rentInfoList]) => {
                    //Items 테이블 status 업데이트
                    const updatePromises = targetItemList.map(item =>
                        new Promise((resolve, reject) => {
                            const sqlUpdateStatus = 'UPDATE Items SET status = 0 WHERE itemName = ?';
                            db.query(sqlUpdateStatus, [item], (err, result) => {
                                if (err) reject(err);
                                else resolve(result);
                            });
                        })
                    );

                    return Promise.all([Promise.all(updatePromises), rentInfoList]);
                })
                .then(([updateResults, rentInfoList]) => {
                    //Log_rent 반납 처리 + 조건부 연체시간 계산
                    rentInfoList.forEach(rentInfo => {
                        if (!rentInfo.rentTime || !rentInfo.rentToHour) {
                            console.error('대여 정보 누락: ', rentInfo.itemName);
                            return;
                        }

                        // 먼저 연체 여부를 확인
                        const currentTime = new Date();
                        const rentTime = new Date(rentInfo.rentTime);
                        const rentEndTime = new Date(rentTime.getTime() + rentInfo.rentToHour * 60 * 60 * 1000);
                        const isOverdue = currentTime > rentEndTime;

                        //대여 기간 초과 여부 확인 후 연체시간 계산
                        const sqlUpdateLog = `
                            UPDATE Log_rent
                            SET returnTime = NOW(),
                                delinquencyTime = CASE
                                    WHEN NOW() > DATE_ADD(?, INTERVAL ? HOUR)
                                    THEN SEC_TO_TIME(TIMESTAMPDIFF(SECOND, DATE_ADD(?, INTERVAL ? HOUR), NOW()))
                                    ELSE NULL
                                END
                            WHERE name = ? AND itemName = ?
                              AND returnTime IS NULL
                            ORDER BY rentTime DESC
                            LIMIT 1
                        `;

                        db.query(sqlUpdateLog, [
                            rentInfo.rentTime,
                            rentInfo.rentToHour,
                            rentInfo.rentTime,
                            rentInfo.rentToHour,
                            userName,
                            rentInfo.itemName
                        ], (logErr) => {
                            if (logErr) {
                                console.error('[❌ Log_rent UPDATE 실패]: ', logErr);
                                return;
                            }

                            // ✅ 연체가 감지된 경우 rent_perm을 0으로 설정
                            if (isOverdue) {
                                const sqlGetStudentNum = 'SELECT studentNum FROM Users WHERE name = ?';
                                db.query(sqlGetStudentNum, [userName], (err, userResults) => {
                                    if (err) {
                                        console.error('[❌ 사용자 학번 조회 실패]: ', err);
                                        return;
                                    }

                                    if (userResults.length === 0) {
                                        console.error('[❌ 사용자를 찾을 수 없음]: ', userName);
                                        return;
                                    }

                                    const studentNum = userResults[0].studentNum;

                                    // user_permissions에서 rent_perm을 0으로 설정
                                    const sqlUpdatePerm = `
                                        UPDATE user_permissions 
                                        SET rent_perm = 0 
                                        WHERE studentNum = ?
                                    `;

                                    db.query(sqlUpdatePerm, [studentNum], (permErr, permResult) => {
                                        if (permErr) {
                                            console.error('[❌ 권한 제한 실패]', permErr);
                                        } else if (permResult.affectedRows > 0) {
                                            console.log(`[ 연체로 인한 권한 제한] ${userName}(${studentNum}) - 아이템: ${rentInfo.itemName}`);
                                        } else {
                                            console.log(`[⚠️ 권한 제한 대상 없음] ${userName}(${studentNum}) - user_permissions 레코드가 없습니다`);
                                        }
                                    });
                                });
                            }
                        });
                    });

                    callback({ success: true, message: '반납 완료' });
                })
                .catch(err => {
                    console.error('[❌ 반납 처리 중 오류]: ', err);
                    callback({ success: false, message: '반납 처리 실패' });
                });
        });
    });
}

module.exports = router;
